using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Animations;
public static class RepairAngelMotion {
 public static string Run(){const string dir="Assets/Resources/ExpeditionEnemies/";var clips=AssetDatabase.LoadAllAssetsAtPath("Assets/Angel_Knight_Anims/Meshs/Angel Knight/LowPoly_AngelKnight.fbx").OfType<AnimationClip>().ToArray();var idle=clips.First(c=>c.name=="Idle_1");var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(dir+"AngelKnight.controller");foreach(var pair in new[]{("Idle","Idle_1"),("Chase","Sprint_Front_1"),("Run","Sprint_Front_1"),("Melee","Attack_1.1_To_Idle_1"),("SlashB","Attack_1.2_To_Idle_1"),("Slam","Attack_1.3_To_Idle_1"),("Shoot","Spell"),("Nova","Power_Up_1"),("Hit","Damage_1"),("Stun","Damage_1"),("Death","Death_1.2")}){var clip=UnityEngine.Object.Instantiate(clips.First(c=>c.name==pair.Item2));clip.name=pair.Item1;var settings=AnimationUtility.GetAnimationClipSettings(clip);bool loop=pair.Item1=="Idle"||pair.Item1=="Chase"||pair.Item1=="Run";settings.loopTime=loop;settings.loopBlend=loop;AnimationUtility.SetAnimationClipSettings(clip,settings);AnimationUtility.SetAnimationEvents(clip,Array.Empty<AnimationEvent>());
 foreach(var b in AnimationUtility.GetCurveBindings(clip).Where(b=>b.path=="root/root.x"&&b.propertyName.StartsWith("m_LocalPosition."))){var curve=AnimationUtility.GetEditorCurve(clip,b);var reference=AnimationUtility.GetEditorCurve(idle,b);if(reference==null)continue;float baseline=reference.Evaluate(0);if(!b.propertyName.EndsWith(".y"))curve=AnimationCurve.Constant(0,clip.length,baseline);else {float start=curve.Evaluate(0);var keys=curve.keys;for(int i=0;i<keys.Length;i++)keys[i].value=baseline+Mathf.Clamp(keys[i].value-start,-.12f,.35f);curve.keys=keys;}AnimationUtility.SetEditorCurve(clip,b,curve);}
 string path=dir+"Angel_"+pair.Item1+".anim";var target=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);EditorUtility.CopySerialized(clip,target);UnityEngine.Object.DestroyImmediate(clip);EditorUtility.SetDirty(target);var state=controller.layers[0].stateMachine.states.First(s=>s.state.name==pair.Item1).state;state.motion=target;state.speedParameter=loop&&pair.Item1!="Idle"?"LocomotionSpeed":"ActionSpeed";state.speedParameterActive=pair.Item1!="Idle";EditorUtility.SetDirty(state);}
 AssetDatabase.SaveAssets();return "PASS 11 native floating states; root translation aligned; speed follows navigation; no humanoid retarget";}
}
